"""Generate L4Data.lean; Python proposes, Lean's kernel checks every certificate.

Run from the repository root with uv run (project dependencies are locked).
Only writes inside this experiment; no simulation data are changed.
"""
from pathlib import Path
import c1b as c
from c1_ant import parse_canonical

ROOT = Path(__file__).resolve().parents[4]
E = ROOT / "experiments/archive/2026-10-rlrlll-macro-transition"
ph = parse_canonical()
out = ["import Data\nimport IterB\nimport Composition\nimport Cycle\n",
       "/-! GENERATED by scripts/l4_gen.py. End runs are proposals checked by decide +kernel. -/",
       "set_option maxRecDepth 1000000\nset_option maxHeartbeats 0\nnamespace Sweeper\n",
       "def blank : Row := List.replicate 51 0\n"]
w = out.append
row = lambda r: "[" + ", ".join(map(str, r)) + "]"
rows = lambda rs: "[" + ",\n  ".join(row(r) for r in rs) + "]"
st = lambda g, x, y, h: f"({{ g := {g}, x := {x}, y := {y}, h := {h} }} : St)"
for q in range(3):
    p, nq = ph[q], ph[(q + 1) % 3]
    d = c.verify_phase("RLRLLL", ph, q, [], 100)["_data"]
    top, bottom = [c.ext(r) for r in p["top"]], [c.ext(r) for r in p["bottom"]]
    s1in = [c.BLANK] * c.NB + top + [d["bulk"]]
    e1, s1, pos1, h1, _ = c.run("RLRLLL", s1in, (p["dx"], c.NB+p["dy"]), p["h"], lambda a: a.pos[1] == len(s1in))
    U = e1[:-1]
    s3in = d["A"] + [d["bulk"]] + bottom + [c.BLANK] * c.NB
    e3, s3, pos3, h3, _ = c.run("RLRLLL", s3in, (d["x1"], 1), d["h1"], lambda a: a.pos[1] == -1)
    D3 = e3[1:]
    e5, s5, pos5, h5, _ = c.run("RLRLLL", U+d["Ap"], (pos3[0], len(U)-1), h3, lambda a: a.pos[0] == -3, xfloor=-3)
    assert s1 == (387,383,383)[q] and s3 == 216 and s5 == (355,483,323)[q]
    t0 = pos5[1] - nq["dy"]
    a = len(e5) - t0 - len(nq["top"])
    b = 4-a
    tail = len(e5) + len(D3) - t0 - len(nq["top"]) - 4 - len(nq["bottom"])
    assert min(t0,a,b,tail) >= 0
    for name, rs in [("top",top),("bottom",bottom),("U",U),("D3",D3),("E5",e5),
                     ("nextTop",[c.ext(r) for r in nq["top"]]),("nextBottom",[c.ext(r) for r in nq["bottom"]])]:
        w(f"def {name}{q} : List Row := {rows(rs)}\n")
    w(f"def initial{q} (n : Nat) : St := {st(f'List.replicate 14 blank ++ top{q} ++ List.replicate (2 + 2*n) bulk{q} ++ bottom{q} ++ List.replicate 14 blank',p['dx'],14+p['dy'],p['h'])}\n")
    w(f"def final{q} (n : Nat) : St := {st(f'E5{q} ++ (List.replicate n rpp{q}).flatten ++ D3{q}',pos5[0],pos5[1],h5)}\n")
    w(f"theorem s1_cert{q} : runB {s1} {st(f'List.replicate 14 blank ++ top{q} ++ [bulk{q}]',p['dx'],14+p['dy'],p['h'])} = some {st(f'U{q} ++ [A{q}]',pos1[0],pos1[1],h1)} := by decide +kernel\n")
    w(f"theorem s3_cert{q} : runB {s3} {st(f'[A{q}, bulk{q}] ++ bottom{q} ++ List.replicate 14 blank',pos1[0],1,h1)} = some {st(f'[Ap{q}] ++ D3{q}',pos3[0],-1,h3)} := by decide +kernel\n")
    w(f"theorem s5_cert{q} : runB {s5} {st(f'U{q} ++ [Ap{q}]',pos3[0],len(U)-1,h3)} = some {st(f'E5{q}',pos5[0],pos5[1],h5)} := by decide +kernel\n")
    w(f"theorem descent_certB{q} : runB 20 {st(f'[A{q}, bulk{q}, bulk{q}]',-1,1,2)} = some {st(f'rp{q} ++ [A{q}]',-1,3,2)} := by decide +kernel\n")
    w(f"theorem return_certB{q} : runB 4 {st(f'rp{q} ++ [Ap{q}]',1,1,0)} = some {st(f'[Ap{q}] ++ rpp{q}',1,-1,0)} := by decide +kernel\n")
    w(f"theorem e5_shift{q} : E5{q}.map shiftRow = List.replicate {t0} blank ++ nextTop{q} ++ List.replicate {a} bulk{(q+1)%3} := by decide +kernel\n")
    w(f"theorem d3_shift{q} : D3{q}.map shiftRow = List.replicate {b} bulk{(q+1)%3} ++ nextBottom{q} ++ List.replicate {tail} blank := by decide +kernel\n")
    w(f"theorem band_shift{q} : rpp{q}.map shiftRow = [bulk{(q+1)%3}, bulk{(q+1)%3}] := by decide +kernel\n")
    w(f"theorem composition{q} (n : Nat) : (final{q} n).g.map shiftRow = List.replicate {t0} blank ++ nextTop{q} ++ List.replicate (2*n+4) bulk{(q+1)%3} ++ nextBottom{q} ++ List.replicate {tail} blank := by\n  have hc := compose_band E5{q} D3{q} rpp{q} (List.replicate {t0} blank ++ nextTop{q}) (nextBottom{q} ++ List.replicate {tail} blank) bulk{(q+1)%3} {a} {b} e5_shift{q} d3_shift{q} band_shift{q} n\n  simpa [final{q}, List.append_assoc, show 2 + 2*n + 2 = 2*n+4 by omega] using hc\n")
    w(f"theorem clock{q} (n : Nat) : {s1} + 20*n + 216 + 4*n + {s5} = 12*(2+2*n) + {(934,1058,898)[q]} := by omega\n")
    clock = f"12*(2+2*n) + {(934,1058,898)[q]}"
    w(f"theorem cycle{q} (n : Nat) : runB ({clock}) (initial{q} n) = some (final{q} n) := by\n  rw [← clock{q} n]\n  have hc := cycle_chain (List.replicate 14 blank ++ top{q}) (bottom{q} ++ List.replicate 14 blank) U{q} D3{q} E5{q} bulk{q} A{q} Ap{q} rp{q} rpp{q} {14+p['dy']} {pos5[1]} {s1} {s5} rfl s1_cert{q} descent_certB{q} s3_cert{q} return_certB{q} s5_cert{q} n\n  simpa only [initial{q}, final{q}, List.append_assoc] using hc\n")
    w(f"theorem cycle_runN{q} (n : Nat) : runN ({clock}) (initial{q} n) = some (final{q} n) := runB_runN _ _ _ (cycle{q} n)\n")
    w(f"theorem first_arrival{q} (n i : Nat) (u : St) (hi : i < {clock}) (hu : runN i (initial{q} n) = some u) : -2 ≤ u.x ∧ u.x ≤ 47 := runB_prefix _ _ _ _ _ (cycle{q} n) hi hu\n")
    w(f"theorem target_ant{q} (n : Nat) : (final{q} n).x + 3 = {nq['dx']} ∧ (final{q} n).y - {t0} = {nq['dy']} ∧ (final{q} n).h = {nq['h']} := by exact ⟨rfl, rfl, rfl⟩\n")
    w(f"-- phase {q}: U length {len(U)}, target top offset {t0}, bulk split {a}+{b}, trailing blanks {tail}; final ant y {pos5[1]}.\n")
w("end Sweeper\n")
(E / "lean/L4Data.lean").write_text("\n".join(out))


